<template><view class="page"><view class="title heading">接单工作台</view><view v-if="!auth.isPlayer" class="card muted">当前账号没有陪玩师角色，无法进入接单功能。</view><template v-else><view class="card"><view class="row"><view><view>当前状态</view><view class="status">{{ data.workStatus || '-' }}</view></view><button size="mini" @click="toggle">{{ data.workStatus==='AVAILABLE'?'休息':'开始接单' }}</button></view></view><view class="card action" @click="dispatches">待响应派单 <text>查看 ›</text></view><view class="card action" @click="orders">我的服务订单 <text>查看 ›</text></view></template></view></template>
<script setup lang="ts">import{ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{getWorkbench,updateWorkStatus}from'@/api/player';import{useAuthStore}from'@/stores/auth';import type{RecordData}from'@/types/api';const auth=useAuthStore(),data=ref<RecordData>({});onShow(async()=>{if(auth.isPlayer)data.value=await getWorkbench()});async function toggle(){await updateWorkStatus(data.value.workStatus==='AVAILABLE'?'OFFLINE':'AVAILABLE');data.value=await getWorkbench()}const dispatches=()=>uni.navigateTo({url:'/subpackages/player/dispatches'});const orders=()=>uni.navigateTo({url:'/subpackages/player/orders'})</script>
<style scoped>.heading{margin:16rpx 0 30rpx}.row,.action{display:flex;align-items:center;justify-content:space-between}.status{font-size:38rpx;color:#7357ff;font-weight:700;margin-top:12rpx}.action text{color:#8d94a5}</style>
